// ─── Execution ────────────────────────────────────────────────────────────────
const tools = JSON.parse(fs.readFileSync(TOOLS_FILE, 'utf8'));

let classified = 0;
let alreadyHad = 0;
let stillUnknown = 0;

tools.forEach(tool => {
  if (!tool.contentReviewRequired) { alreadyHad++; return; }
  
  const map = CLASSIFICATION_MAP[tool.id];
  if (map) {
    tool.category = map.category;
    tool.primaryUseCases = map.primaryUseCases;
    tool.dataProvenance = {
      identity: 'official_source_verified',
      pricing: 'unknown',
      useCases: 'derived',
      category: 'derived',
      lifecycle: 'unknown'
    };
    classified++;
  } else {
    stillUnknown++;
  }
});

fs.writeFileSync(TOOLS_FILE, JSON.stringify(tools, null, 2));

console.log('=== 4G.1 Enrichment Complete ===');
console.log('Legacy tools (untouched):', alreadyHad);
console.log('New tools classified:', classified);
console.log('New tools still unknown:', stillUnknown);
console.log('Total:', tools.length);

const catCounts = {};
tools.forEach(t => { const c = t.category || 'unknown'; catCounts[c] = (catCounts[c]||0)+1; });
console.log('\n=== Final Category Distribution ===');
Object.entries(catCounts).sort((a,b) => b[1]-a[1]).forEach(([c,n]) => console.log(c + ': ' + n));
